package com.apple.spark;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import com.apple.spark.core.BPGStatsdConfig;
import com.codahale.metrics.MetricRegistry;
import com.codahale.metrics.health.HealthCheckRegistry;
import io.dropwizard.jersey.setup.JerseyEnvironment;
import io.dropwizard.setup.Environment;
import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.Collections;
import org.eclipse.jetty.servlet.ServletContextHandler;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.mockito.Mockito;

public class BPGApplicationTest {

  private Environment environment;
  private JerseyEnvironment jerseyEnvironment;
  private ServletContextHandler servletContextHandler;
  private HealthCheckRegistry healthCheckRegistry;
  private MetricRegistry metricRegistry;

  @BeforeEach
  public void setUp() {
    environment = mock(Environment.class);
    jerseyEnvironment = mock(JerseyEnvironment.class);
    servletContextHandler = mock(ServletContextHandler.class);
    healthCheckRegistry = mock(HealthCheckRegistry.class);
    metricRegistry = new MetricRegistry();

    when(environment.jersey()).thenReturn(jerseyEnvironment);
    when(environment.getApplicationContext()).thenReturn(servletContextHandler);
    when(environment.metrics()).thenReturn(metricRegistry);
    when(environment.healthChecks()).thenReturn(healthCheckRegistry);

    // Allow registering anything without side effects
    doNothing().when(jerseyEnvironment).register(Mockito.any());
  }

  @Test
  public void testRun_nullContextPath_usesDefaultAndRegistersResources() {
    AppConfig config = new AppConfig();
    // explicit set to null to exercise null branch
    config.setApplicationContextPath(null);
    config.setAllowedUsers(Arrays.asList("allowed"));
    config.setBlockedUsers(Arrays.asList("blocked"));
    config.setSparkClusters(null);

    BPGApplication app = new BPGApplication(false);
    app.run(config, environment);

    // Verify context path set to default when null
    ArgumentCaptor<String> contextCaptor = ArgumentCaptor.forClass(String.class);
    verify(servletContextHandler).setContextPath(contextCaptor.capture());
    String contextPathSet = contextCaptor.getValue();
    assertNotNull(contextPathSet);
    assertFalse(contextPathSet.isEmpty());
    assertEquals(com.apple.spark.core.Constants.DEFAULT_APPLICATION_CONTEXT_PATH, contextPathSet);

    // Verify metric registry added to SharedMetricRegistries under default name
    MetricRegistry obtained = com.codahale.metrics.SharedMetricRegistries.getOrCreate(
        com.apple.spark.core.Constants.DEFAULT_METRIC_REGISTRY);
    assertSame(metricRegistry, obtained);

    // Verify resources registration (some expected calls)
    verify(jerseyEnvironment, atLeast(1)).register(Mockito.any());
    // Verify healthcheck registration called with "sparkClusters"
    verify(healthCheckRegistry).register(eq("sparkClusters"), Mockito.any());
  }

  @Test
  public void testRun_customContextPath_monitorApplicationTrue_and_invokePrivateSendPeriodicMetrics()
      throws Exception {
    AppConfig config = new AppConfig();
    config.setApplicationContextPath("/custom");
    config.setAllowedUsers(Collections.emptyList());
    config.setBlockedUsers(Collections.emptyList());
    // Keep sparkClusters null to avoid heavy informer logic in ApplicationMonitor.start
    config.setSparkClusters(null);

    // Create application with monitoring enabled to exercise monitorApplication branch
    BPGApplication app = new BPGApplication(true);

    // Run should not throw even when monitorApplication true (daemon threads may be started)
    app.run(config, environment);

    // Verify context path set to provided value
    verify(servletContextHandler).setContextPath("/custom");

    // Also verify that Jersey registers components
    verify(jerseyEnvironment, atLeast(1)).register(Mockito.any());

    // Now use reflection to invoke the private sendPeriodicMetrics method directly
    Method sendPeriodicMetrics =
        BPGApplication.class.getDeclaredMethod("sendPeriodicMetrics", AppConfig.class,
            io.micrometer.core.instrument.MeterRegistry.class);
    sendPeriodicMetrics.setAccessible(true);

    // Use createMeterRegistry to get a MeterRegistry instance
    io.micrometer.core.instrument.MeterRegistry meterRegistry = BPGStatsdConfig.createMeterRegistry();

    // Invoke the private method; it should schedule a Timer task and not throw
    sendPeriodicMetrics.invoke(app, config, meterRegistry);

    // If we reached here, the private method executed without throwing
    assertTrue(true);
  }
}

